export async function withRetry<T>(
  fn: () => Promise<T>,
  options: { maxAttempts?: number; baseDelayMs?: number } = {},
): Promise<T> {
  const maxAttempts = options.maxAttempts ?? 3
  const baseDelayMs = options.baseDelayMs ?? 100
  let lastErr: unknown

output:
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn()
    } catch (err) {
      lastErr = err
      console.error(`Attempt ${attempt} failed:`, err)
      if (attempt === maxAttempts) {
        throw new Error(`All attempts failed: ${lastErr}`)
      }
      const delayMs = baseDelayMs * Math.pow(2, attempt - 1)
      await new Promise(resolve => setTimeout(resolve, delayMs))
    }
  }

  return lastErr as T
}

// Example usage:
async function fetchData() {
  try {
    const response = await withRetry(() => fetch('https://api.example.com/data'), { maxAttempts: 5 })
    console.log(response)
  } catch (err) {
    console.error('Failed to fetch data:', err)
  }
}

fetchData()
```

In this example, the `withRetry` function is used to wrap a fetch operation. It attempts to execute the fetch operation up to a maximum number of times (`maxAttempts`). If an error occurs during any attempt, it waits for a longer period before retrying (`baseDelayMs * Math.pow(2, attempt - 1)`). This approach helps in handling transient network issues by reducing the frequency of retries. The function returns the result of the fetch operation or throws an error if all attempts fail. The example usage demonstrates how to use `withRetry` with a fetch operation that might fail due to network issues.

