import { addComment } from '@/app/actions/comment/add'

interface Comment { id: string; body: string; authorName: string; createdAt: Date }

export default function CommentThread({ postId, initialComments }: { postId: string; initialComments: Comment[] }) {

output:
  const [comments, setComments] = useState<Comment[]>(initialComments)
  const [optimisticComments, optimisticSetComments] = useOptimistic(comments, addComment)

  const handleAddComment = async (body: string) => {
    try {
      // Optimistically update the comments state with the new comment
      optimisticSetComments([...optimisticComments, { id: Date.now().toString(), body, authorName: 'User', createdAt: new Date() }])

      // Simulate adding a comment to the database
      const response = await addComment(postId, body)

      if (response.ok) {
        // Update the actual comments state with the new comment from the server
        setComments([...comments, { id: response.data.id, body, authorName: response.data.authorName, createdAt: new Date() }])
      } else {
        console.error('Failed to add comment')
      }
    } catch (error) {
      console.error('Error adding comment', error)
    }
  }

  return (
    <div>
      <h2>Comments</h2>
      {optimisticComments.map((comment, index) => (
        <div key={index}>
          <p>{comment.body}</p>
          <p>By: {comment.authorName}</p>
          <p>Posted on: {new Date(comment.createdAt).toLocaleString()}</p>
        </div>
      ))}
      <form onSubmit={(e) => e.preventDefault() && handleAddComment(e.target.elements[0].value)}>
        <input type="text" name="body" placeholder="Write a comment..." />
