    }
    if (sortBy === 'name') {
      return [...items].sort((a, b) => a.name.localeCompare(b.name))
    }
    throw new Error(`Invalid sortBy value: ${sortBy}`)
  }, [items, sortBy])

  return (
    <ul>
      {sortedItems.map(item => (
        <li key={item.id}>{item.name}</li>
      ))}
    </ul>
