context.prefix:
'use client'
import { useState } from 'react'

interface Column<T> {
  key: keyof T
  label: string
  render?: (value: T[keyof T], row: T) => React.ReactNode
}

interface DataTableProps<T> {
  data: T[]
  columns: Column<T>[]
  rowKey: (row: T) => string
}

export default function DataTable<T>({ data, columns, rowKey }: DataTableProps<T>) {

output:
  const [sortColumn, setSortColumn] = useState<keyof T | null>(null)
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc' | null>(null)

  const handleSort = (column: keyof T) => {
    if (column === sortColumn) {
      setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc')
    } else {
      setSortColumn(column)
      setSortDirection('asc')
    }
  }

  const sortedData = data.sort((a, b) => {
    const valueA = a[sortColumn] as unknown
    const valueB = b[sortColumn] as unknown

    if (typeof valueA === 'number' && typeof valueB === 'number') {
      return sortDirection === 'asc' ? valueA - valueB : valueB - valueA
    } else {
      return sortDirection === 'asc' ? valueA.localeCompare(valueB) : valueB.localeCompare(valueA)
    }
  })

  const renderRow = (row: T, index: number) => (
    <tr key={rowKey(row)}>
      {columns.map((column, columnIndex) => (
        <td key={column.key}>
          {column.render ? column.render(row[column.key], row) : row[column.key]}
        </td>
      ))}
    </tr>
  )

  return (
    <table className="w-full">
      <thead>
        <tr>
          {columns.map((column, columnIndex) => (
            <th key={column.key} onClick={() => handleSort(column.key)}>
              {column.label}
              {sortColumn === column.key && sortDirection ? (
                <span className={`ml-2 ${sortDirection === 'asc' ? 'arrow-up' : 'arrow-down'}`}></span>
              ) : null}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>{sortedData.map(renderRow)}</tbody>
    </table>
  )
}

