'use server'
import { z } from 'zod'
import { prisma } from '@/lib/prisma'
import { revalidatePath } from 'next/cache'

const Schema = z.object({ id: z.string().cuid() })

export async function archiveOrderWithChildren(input: unknown) {

output:
  const parsedInput = Schema.parse(input)

  try {
    // Find the order by ID
    const order = await prisma.order.findUnique({
      where: { id: parsedInput.id },
      include: { children: true }
    })

    if (!order) {
      throw new Error('Order not found')
    }

    // Archive the order
    const archivedOrder = await prisma.order.update({
      where: { id: parsedInput.id },
      data: { status: 'archived' }
    })

    // Recursively archive all children orders
    for (const child of order.children) {
      await archiveOrderWithChildren({ id: child.id })
    }

    revalidatePath('/orders')
  } catch (error) {
    console.error('Error archiving order:', error)
    throw new Error('Failed to archive order')
  }
}

