'use client'
import { useState, useEffect } from 'react'

interface Command {
  id: string
  label: string
  shortcut?: string
  onSelect: () => void
}

export default function CommandPalette({ commands }: { commands: Command[] }) {

output:
  const [activeCommandId, setActiveCommandId] = useState<string | null>(null)

  useEffect(() => {
    // Handle keydown events to activate the command with the corresponding shortcut
    document.addEventListener('keydown', (event) => {
      if (!event.ctrlKey && !event.metaKey) return

      commands.forEach((command) => {
        if (command.shortcut === event.key) {
          setActiveCommandId(command.id)
          break
        }
      })
    })

    // Handle keyup events to deactivate the command when the shortcut is released
    document.addEventListener('keyup', (event) => {
      if (!event.ctrlKey && !event.metaKey) return

      commands.forEach((command) => {
        if (command.shortcut === event.key) {
          setActiveCommandId(null)
          break
        }
      })
    })

    // Clean up the event listeners when the component unmounts
    return () => {
      document.removeEventListener('keydown', handleKeyDown)
      document.removeEventListener('keyup', handleKeyUp)
    }
  }, [commands])

  const handleSelect = (commandId: string) => {
    setActiveCommandId(commandId)
  }

  if (!activeCommandId) {
    return null
  }

  const command = commands.find((cmd) => cmd.id === activeCommandId)

  if (!command) {
    throw new Error(`Command with id ${activeCommandId} not found`)
  }

  return (
    <div className="bg-white shadow-lg rounded-md p-4">
      <h2 className="text-xl font-bold mb-2">{command.label}</h2>
      <button
        onClick={() => handleSelect(command.id)}
        className="w-full py-2 bg-blue-500 text-white rounded-md hover:bg-blue-600"
      >
        Select
      </button>
    </div>
  )
}

