// Type-safe event emitter — events typed as a record
type EventMap = Record<string, unknown>

export class TypedEmitter<E extends EventMap> {

context.prefix:
// Type-safe event emitter — events typed as a record
type EventMap = Record<string, unknown>

export class TypedEmitter<E extends EventMap> {

output:
  private listeners: Map<string, ((event: E[keyof E]) => void)[]> = new Map()

  on(event: keyof E, listener: (event: E[keyof E]) => void): this {
    const listeners = this.listeners.get(event) || []
    listeners.push(listener)
    this.listeners.set(event, listeners)
    return this
  }

  off(event: keyof E, listener: (event: E[keyof E]) => void): this {
    const listeners = this.listeners.get(event) || []
    const index = listeners.indexOf(listener)
    if (index !== -1) {
      listeners.splice(index, 1)
      this.listeners.set(event, listeners)
    }
    return this
  }

  emit(event: keyof E, data?: unknown): boolean {
    const listeners = this.listeners.get(event) || []
    for (const listener of listeners) {
      try {
        listener(data)
      } catch (error) {
        console.error(`Error emitting event ${event}:`, error)
      }
    }
    return true
  }

  once(event: keyof E, listener: (event: E[keyof E]) => void): this {
    const wrapper = (...args: unknown[]) => {
      this.off(event, wrapper)
      listener(...args)
    }
    this.on(event, wrapper)
    return this
  }
}

// Example usage:
const emitter = new TypedEmitter<{ message: string }>()

emitter.on('message', (msg) => console.log(msg))

emitter.emit('message', 'Hello, world!')

emitter.off('message', (msg) => console.log(msg)) // This won't log anything

emitter.once('message', (msg) => console.log(msg)) // This will only log once
```

In this solution, we define a `TypedEmitter` class that can handle events of type `E`. The `EventMap` is a generic type that allows for any number of event types. The `on`, `off`, `emit`, and `once` methods are implemented to manage the listeners for each event type. The `emit` method also includes error handling to catch any exceptions thrown by the listener functions. This ensures that the events are handled safely and correctly. The example usage demonstrates how to use the `TypedEmitter` class to emit and listen to events of different types.

